import express from "express";
import path from "path";
import fs from "fs";
import { createServer as createViteServer } from "vite";
import { GoogleGenAI } from "@google/genai";

// Persistent shared birthdays storage
const DATA_DIR = path.join(process.cwd(), 'data');
const DATA_FILE = path.join(DATA_DIR, 'shared_birthdays.json');

// Time rules:
// 1. Play / viewing validity is strictly 7 days
const PLAY_VALIDITY_MS = 7 * 24 * 60 * 60 * 1000;
// 2. Storage retention & reservation is 30 days. After 30 days, auto-removed and recycled for new users!
const PURGE_AFTER_MS = 30 * 24 * 60 * 60 * 1000;

let sharedBirthdays: Record<string, { code: string; data: any; savedAt: number }> = {};

function initStorage() {
  try {
    if (!fs.existsSync(DATA_DIR)) {
      fs.mkdirSync(DATA_DIR, { recursive: true });
    }
    if (fs.existsSync(DATA_FILE)) {
      const content = fs.readFileSync(DATA_FILE, 'utf-8');
      sharedBirthdays = JSON.parse(content);
      purgeExpiredCodes();
    }
  } catch (err) {
    console.error('Failed to initialize shared birthdays storage:', err);
    sharedBirthdays = {};
  }
}

function persistStorage() {
  try {
    if (!fs.existsSync(DATA_DIR)) {
      fs.mkdirSync(DATA_DIR, { recursive: true });
    }
    fs.writeFileSync(DATA_FILE, JSON.stringify(sharedBirthdays, null, 2), 'utf-8');
  } catch (err) {
    console.error('Failed to persist shared birthdays storage:', err);
  }
}

function purgeExpiredCodes(): boolean {
  const now = Date.now();
  let changed = false;
  for (const [code, item] of Object.entries(sharedBirthdays)) {
    if (!item || !item.savedAt || (now - item.savedAt > PURGE_AFTER_MS)) {
      delete sharedBirthdays[code];
      changed = true;
      console.log(`[Auto-Purge] Code #${code} was automatically purged after 30 days. It is now free for new users to register.`);
    }
  }
  if (changed) {
    persistStorage();
  }
  return changed;
}

async function startServer() {
  initStorage();

  // Run periodic purge every hour
  setInterval(() => {
    purgeExpiredCodes();
  }, 60 * 60 * 1000);

  const app = express();
  const PORT = 3000;

  // Set higher limit to allow photos in payload
  app.use(express.json({ limit: '30mb' }));
  app.use(express.urlencoded({ extended: true, limit: '30mb' }));

  // ==========================================
  // SHARED BIRTHDAYS WITH 6-DIGIT CODE APIS
  // ==========================================

  // Check code availability endpoint
  app.get("/api/birthdays/check/:code", (req, res) => {
    purgeExpiredCodes();
    const code = req.params.code?.trim();
    const cardId = (req.query.cardId as string)?.trim();
    if (!code || !/^\d{6}$/.test(code)) {
      return res.status(400).json({ success: false, error: "Invalid 6-digit code format" });
    }

    let existing = sharedBirthdays[code];
    if (!existing && fs.existsSync(DATA_FILE)) {
      try {
        const fresh = JSON.parse(fs.readFileSync(DATA_FILE, 'utf-8'));
        if (fresh[code]) {
          sharedBirthdays[code] = fresh[code];
          existing = sharedBirthdays[code];
        }
      } catch {}
    }

    if (!existing) {
      return res.json({ success: true, available: true, code });
    }

    // If it belongs to the same card instance, it is allowed for editing
    if (cardId && existing.data && existing.data.id === cardId) {
      return res.json({ success: true, available: true, isOwner: true, code });
    }

    // Otherwise occupied within 30 days
    const ageMs = Date.now() - existing.savedAt;
    const daysLeftForPurge = Math.max(1, Math.ceil((PURGE_AFTER_MS - ageMs) / (24 * 60 * 60 * 1000)));

    return res.json({
      success: true,
      available: false,
      code,
      message: `यो कोड #${code} पहिले नै अर्को युजरले प्रयोग गरिरहनुभएको छ। कृपया अर्को नयाँ कोड राख्नुहोस्!`,
      daysLeftForPurge
    });
  });

  // Save birthday with 6-digit code (checks uniqueness & 30-day recycling)
  app.post("/api/birthdays/save", (req, res) => {
    try {
      purgeExpiredCodes();
      let { code, data } = req.body;
      if (!data) {
        return res.status(400).json({ success: false, error: "Missing birthday data" });
      }

      // Ensure valid 6-digit code
      if (!code || typeof code !== 'string' || !/^\d{6}$/.test(code.trim())) {
        code = Math.floor(100000 + Math.random() * 900000).toString();
      } else {
        code = code.trim();
      }

      // Check if code is already taken by a different card within 30 days
      let existing = sharedBirthdays[code];
      if (!existing && fs.existsSync(DATA_FILE)) {
        try {
          const fresh = JSON.parse(fs.readFileSync(DATA_FILE, 'utf-8'));
          if (fresh[code]) {
            sharedBirthdays[code] = fresh[code];
            existing = sharedBirthdays[code];
          }
        } catch {}
      }

      if (existing && existing.data) {
        const existingCardId = existing.data.id;
        const incomingCardId = data.id;
        const isSameName = existing.data.name && data.name &&
          existing.data.name.trim().toLowerCase() === data.name.trim().toLowerCase();

        if (!isSameName && existingCardId && incomingCardId && existingCardId !== incomingCardId) {
          const ageMs = Date.now() - (existing.savedAt || Date.now());
          const daysUntilPurge = Math.max(1, Math.ceil((PURGE_AFTER_MS - ageMs) / (24 * 60 * 60 * 1000)));
          return res.status(409).json({
            success: false,
            codeConflict: true,
            code,
            daysUntilPurge,
            error: `यो कोड #${code} पहिले नै अर्को युजरले प्रयोग गरिरहनुभएको छ। कृपया New Code थिचेर नयाँ कोड राख्नुहोस्! (${daysUntilPurge} दिनपछि यो कोड स्वत: खुला हुनेछ)`
          });
        }
      }

      // Ensure data has an ID
      if (!data.id) {
        data.id = `card_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
      }
      data.code = code;
      data.updatedAt = Date.now();

      sharedBirthdays[code] = {
        code,
        data,
        savedAt: Date.now()
      };

      persistStorage();

      console.log(`Saved birthday for "${data.name}" with 6-digit code: ${code} (CardId: ${data.id})`);
      return res.json({
        success: true,
        code,
        cardId: data.id,
        savedAt: sharedBirthdays[code].savedAt,
        message: `Birthday saved successfully with unique 6-digit code: ${code}`
      });
    } catch (err: any) {
      console.error("Error saving shared birthday:", err);
      return res.status(500).json({ success: false, error: err.message || "Failed to save" });
    }
  });

  // Get birthday by 6-digit code (checks 7-day viewing limit & 30-day purge)
  app.get("/api/birthdays/:code", (req, res) => {
    try {
      purgeExpiredCodes();
      const code = req.params.code?.trim();
      if (!code || !/^\d{6}$/.test(code)) {
        return res.status(400).json({ success: false, error: "Invalid 6-digit code format" });
      }

      let item = sharedBirthdays[code];
      if (!item && fs.existsSync(DATA_FILE)) {
        try {
          const fresh = JSON.parse(fs.readFileSync(DATA_FILE, 'utf-8'));
          if (fresh[code]) {
            sharedBirthdays[code] = fresh[code];
            item = sharedBirthdays[code];
          }
        } catch {}
      }

      if (!item || !item.data) {
        return res.status(404).json({
          success: false,
          notFound: true,
          error: `यो कोड #${code} सँग कुनै Birthday Card भेटिएन वा ३० दिन कटेर हटिसकेको छ। कोड जाँच्नुहोस्।`
        });
      }

      // Check 7-day play validity!
      const savedAt = item.savedAt || Date.now();
      const ageMs = Date.now() - savedAt;
      if (ageMs > PLAY_VALIDITY_MS) {
        const daysUntilFree = Math.max(1, Math.ceil((PURGE_AFTER_MS - ageMs) / (24 * 60 * 60 * 1000)));
        return res.status(410).json({
          success: false,
          expired: true,
          code,
          savedAt,
          daysUntilFree,
          error: `यो कोड (#${code}) को म्याद (७ दिन) समाप्त भइसकेको छ! ३० दिन पुगेपछि (बाँकी ${daysUntilFree} दिनमा) यो कोड स्वत: हटेर पुनः नयाँ बनाउन मिल्नेछ।`
        });
      }

      const daysLeft = Math.ceil((PLAY_VALIDITY_MS - ageMs) / (24 * 60 * 60 * 1000));

      return res.json({
        success: true,
        code,
        data: item.data,
        savedAt: item.savedAt,
        validDaysLeft: daysLeft
      });
    } catch (err: any) {
      console.error("Error fetching birthday by code:", err);
      return res.status(500).json({ success: false, error: "Server error fetching code" });
    }
  });

  // List all shared codes summary (lightweight)
  app.get("/api/birthdays", (req, res) => {
    const list = Object.values(sharedBirthdays).map((item) => ({
      code: item.code,
      name: item.data?.name || 'Friend',
      age: item.data?.age || '',
      savedAt: item.savedAt
    }));
    return res.json({ success: true, birthdays: list });
  });

  // API route for generating 4 birthday wishes using Gemini AI
  app.post("/api/generate-wishes", async (req, res) => {
    try {
      const { name, age, bio } = req.body;
      const apiKey = process.env.GEMINI_API_KEY;

      if (!apiKey) {
        // Fallback if API key is not configured
        return res.json({
          wishes: [
            `जन्मदिनको धेरै धेरै शुभकामना ${name || 'Dear'}! तपाईंको जीवन सधैं खुशी, सफलता र स्वास्थ्यले भरियोस्। 🎂🎉`,
            `May this special Chapter ${age || '12'} open brilliant new doors to incredible opportunities, joy, and wonderful adventures!`,
            `Here’s to another 365 days of laughter, great memories, and achieving all your dreams. Keep shining bright! ✨`,
            `${bio ? `Inspiration: ${bio}` : 'Keep inspiring everyone around you with your wonderful smile, kindness, and boundless energy! 💖'}`
          ]
        });
      }

      const ai = new GoogleGenAI({ apiKey });
      const prompt = `You are a warm, creative birthday greeting card writer. Generate exactly 4 distinct, heartwarming birthday wishes/messages for ${name || 'our friend'} (Age ${age || '12'}).
Person's bio / personal details: "${bio || 'An amazing soul who brings boundless joy and inspiration.'}"

Requirements:
- Provide exactly 4 distinct birthday wishes (one for each of the 4 card pages / book pages).
- Mix warm Nepali (with English translation or heartfelt Nepali wishes) and inspiring English wishes.
- Keep each wish concise, beautiful, and emotionally touching.
- Return ONLY a valid JSON array of 4 strings, e.g. ["Wish 1", "Wish 2", "Wish 3", "Wish 4"]. No markdown formatting or extra text.`;

      const response = await ai.models.generateContent({
        model: 'gemini-3.6-flash',
        contents: prompt,
      });

      const text = response.text || '';
      const cleaned = text.replace(/```json/g, '').replace(/```/g, '').trim();
      let parsedWishes: string[];
      try {
        parsedWishes = JSON.parse(cleaned);
      } catch (e) {
        parsedWishes = cleaned.split('\n').filter(Boolean).slice(0, 4);
      }

      if (!Array.isArray(parsedWishes) || parsedWishes.length < 4) {
        throw new Error('Invalid AI response format');
      }

      res.json({ wishes: parsedWishes.slice(0, 4) });
    } catch (err: any) {
      console.error('Gemini AI generation error:', err);
      res.json({
        wishes: [
          `जन्मदिनको धेरै धेरै शुभकामना! सदा खुशी र स्वस्थ रहनुहोस्। (Happy Birthday! Wishing you endless health and happiness!)`,
          `May this special year bring immense success, adventure, and joy to your life!`,
          `Here’s to another 365 days of laughter, great memories, and pure happiness.`,
          `Keep shining brightly and inspiring everyone with your warm smile and kind heart!`
        ]
      });
    }
  });

  // Vite middleware setup
  if (process.env.NODE_ENV !== "production") {
    const vite = await createViteServer({
      server: {
        middlewareMode: true,
        watch: {
          ignored: ['**/data/**', '**/*.json', '**/dist/**', '**/.git/**', '**/tmp/**'],
        },
      },
      appType: "spa",
    });
    app.use(vite.middlewares);
  } else {
    const distPath = path.join(process.cwd(), 'dist');
    app.use(express.static(distPath));
    app.get('*all', (req, res) => {
      res.sendFile(path.join(distPath, 'index.html'));
    });
  }

  app.listen(PORT, "0.0.0.0", () => {
    console.log(`Server running on http://localhost:${PORT}`);
  });
}

startServer();
